function Field({label,children}:{label:string;children:React.ReactNode}) { return <label className="min-w-0"><span className="mb-1.5 block text-[11px] font-black uppercase tracking-[0.08em] text-black/45">{label}</span>{children}</label>; }
function MoneyInput({value,onChange}:{value:string;onChange:(v:string)=>void}) { return <div className="relative"><span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 font-bold text-black/45">£</span><BmsInput type="number" min="0" step="0.01" value={value} onChange={e=>onChange(e.target.value)} className={`${input} pl-7`}/></div>; }

